// Model files served to the 3D viewers. Optimized variants are generated by
// scripts/model-pipeline/build.mjs; the originals stay in public/models untouched.
//
// ROLLBACK: set NEXT_PUBLIC_USE_OPTIMIZED_MODELS=false (or delete that entry from .env) and
// rebuild to serve the original GLBs again. No code change is needed.
const USE_OPTIMIZED_MODELS = process.env.NEXT_PUBLIC_USE_OPTIMIZED_MODELS !== "false";

type ModelTier = { desktop: string; mobile: string };

const PUMP_ORIGINAL: ModelTier = {
  desktop: "/models/pumpsquare-pump.glb",
  mobile: "/models/pumpsquare-pump-mobile-test.glb",
};

const EQUIPMENT_ORIGINAL: ModelTier = {
  desktop: "/models/homelastsection.glb",
  mobile: "/models/homelastsection-mobile-test.glb",
};

const PUMP_OPTIMIZED_V2: ModelTier = {
  desktop: "/models/pump-desktop-v2.glb",
  mobile: "/models/pump-mobile-v2.glb",
};

const EQUIPMENT_OPTIMIZED_V2: ModelTier = {
  desktop: "/models/last-desktop-v2.glb",
  mobile: "/models/last-mobile-v2.glb",
};

export const PUMP_MODELS = USE_OPTIMIZED_MODELS ? PUMP_OPTIMIZED_V2 : PUMP_ORIGINAL;
export const EQUIPMENT_MODELS = USE_OPTIMIZED_MODELS ? EQUIPMENT_OPTIMIZED_V2 : EQUIPMENT_ORIGINAL;
